# Side imports
import json
from enum import Enum
from web3 import Web3
from eth_utils import crypto, to_bytes


class KeccakHashedEnum(str, Enum):
    """
    The factory for automatic encryption of smart contract event signatures 
    into a unique 32-bit string (so the blockchain understands which events we are expecting).
    Inherit from this class.
    """
    def __new__(cls, signature: str):
        sig_bytes = to_bytes(text=signature)
        raw_hash_bytes = crypto.keccak_256(sig_bytes)
        hashed_value = "0x" + raw_hash_bytes.hex()
        obj = str.__new__(cls, hashed_value)
        obj._value_ = hashed_value
        return obj


# Events regarding money transfers
class pUSDTopics(KeccakHashedEnum):
    # ERC-20 PROTOCOL (pUSD CONTRACT);
    # source: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/master/contracts/token/ERC20/IERC20.sol
    TRANSFER = "Transfer(address,address,uint256)"


# Events regarding shares transfers
class CTFTopics(KeccakHashedEnum):
    # ERC-1155 & CTF-V2 PROTOCOLS (Conditional Tokens CONTRACT); 
    # source: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/master/contracts/token/ERC1155/IERC1155.sol
    # source: https://github.com/gnosis/conditional-tokens-contracts/blob/master/contracts/ConditionalTokens.sol
    TRANSFER_SINGLE   = "TransferSingle(address,address,address,uint256,uint256)"
    TRANSFER_BATCH    = "TransferBatch(address,address,address,uint256[],uint256[])"
    POSITION_SPLIT    = "PositionSplit(address,address,bytes32,bytes32,uint256[],uint256)"    # NOT USED
    POSITIONS_MERGE   = "PositionsMerge(address,address,bytes32,bytes32,uint256[],uint256)"   # NOT USED
    PAYOUT_REDEMPTION = "PayoutRedemption(address,address,bytes32,bytes32,uint256[],uint256)"


